import React, { useState } from 'react';
import axios from 'axios';
import { TextField, Button, Grid, Paper, Typography, Box, Avatar } from '@mui/material';

function ResumeForm({ setResumeData }) {
  const [form, setForm] = useState({
    name: '',
    email: '',
    phone: '',
    summary: '',
    experience: '',
    education: '',
    skills: [],
    hobbies: '',
    languages: '',
  });
  const [skillInput, setSkillInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [image, setImage] = useState(null);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSkillInput = (e) => {
    setSkillInput(e.target.value);
  };

  const handleAddSkill = (e) => {
    e.preventDefault();
    const skill = skillInput.trim();
    if (skill && !form.skills.includes(skill)) {
      setForm({ ...form, skills: [...form.skills, skill] });
    }
    setSkillInput('');
  };

  const handleRemoveSkill = (skill) => {
    setForm({ ...form, skills: form.skills.filter(s => s !== skill) });
  };

  const handleAIEnhance = async () => {
    if (!form.name || !form.email) {
      alert('Please fill in at least your name and email before enhancing with AI.');
      return;
    }
    
    setLoading(true);
    try {
      // First, update the resume data with current form values
      setResumeData(form);
      
      const res = await axios.post('http://localhost:5000/api/ai-resume', form);
      // Update with AI-enhanced data
      setResumeData(res.data);
      alert('Resume enhanced successfully with AI!');
    } catch (err) {
      console.error('AI enhancement error:', err);
      if (err.response?.status === 500) {
        alert('AI enhancement failed. Please check your OpenAI API key in server/.env file and restart the server.');
      } else if (err.code === 'ECONNREFUSED') {
        alert('Cannot connect to server. Please make sure the backend server is running on port 5000.');
      } else {
        alert('AI enhancement failed. Please check your internet connection and try again.');
      }
    }
    setLoading(false);
  };

  // Update resume data whenever form changes
  React.useEffect(() => {
    if (form.name || form.email) {
      setResumeData(form);
    }
  }, [form, setResumeData]);

  const handleSubmit = (e) => {
    e.preventDefault();
    setResumeData({ ...form, image });
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => setImage(ev.target.result);
      reader.readAsDataURL(file);
    }
  };

  return (
    <Box component={Paper} elevation={3} sx={{ p: 4, maxWidth: 600, mx: 'auto', mt: 4 }}>
      <Typography variant="h4" gutterBottom align="center">Resume Builder</Typography>
      <form onSubmit={handleSubmit}>
        <Grid container spacing={2}>
          <Grid item xs={12} sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
            <Avatar src={image} sx={{ width: 80, height: 80, mb: 1 }} />
            <Button variant="outlined" component="label" size="small">
              Upload Photo
              <input type="file" accept="image/*" hidden onChange={handleImageChange} />
            </Button>
          </Grid>
          <Grid item xs={12}>
            <TextField label="Full Name" name="name" value={form.name} onChange={handleChange} fullWidth required />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField label="Email" name="email" value={form.email} onChange={handleChange} fullWidth required />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField label="Phone" name="phone" value={form.phone} onChange={handleChange} fullWidth required />
          </Grid>
          <Grid item xs={12}>
            <TextField label="Professional Summary" name="summary" value={form.summary} onChange={handleChange} fullWidth multiline rows={3} />
          </Grid>
          <Grid item xs={12}>
            <TextField label="Experience" name="experience" value={form.experience} onChange={handleChange} fullWidth multiline rows={3} />
          </Grid>
          <Grid item xs={12}>
            <TextField label="Education" name="education" value={form.education} onChange={handleChange} fullWidth multiline rows={2} />
          </Grid>
          <Grid item xs={12}>
            <TextField label="Skills (comma separated)" name="skills" value={form.skills} onChange={handleChange} fullWidth />
          </Grid>
          <Grid item xs={12}>
            <Button type="submit" variant="contained" color="primary" fullWidth size="large">Generate Resume</Button>
          </Grid>
        </Grid>
      </form>
    </Box>
  );
}

export default ResumeForm;
